scwin.dlt_ondataload = function() {debugger; console.log("scwin.dlt_ondataload"); setTimeout(()=>{ // setTimeout을 넣는 이유 : 안넣으면 그리드 로드 프로세스가 아직 안끝난 시점이라 첨부, 의견 프로세스 바로 태우면 꼬임(의견 칼럼 제대로 오출력). setTimeout을 안쓰고 시점문제를 해결할 수 있는 좋은 방법이 있다면 그 방법으로 개선 요망.
const opinionColumnIndex = scwin.grd[scwin.currentTabIndex].getColumnIndex('opinion'); const atflColumnIndex = scwin.grd[scwin.currentTabIndex].getColumnIndex('atfl'); debugger;
if (scwin.dlt[scwin.currentTabIndex].getRowCount() > 0) { $.each(scwin.dlt[scwin.currentTabIndex].getAllJSON(), function (index, item) {
const atrzOponCttYn = scwin.dlt[scwin.currentTabIndex].getCellData(index, "atrzOponCttYn"); const ecazAtflYn = scwin.dlt[scwin.currentTabIndex].getCellData(index, "ecazAtflYn"); // let opinionCellDom = tbodyDom.children[index].children[opinionColumnIndex]; // let atflCellDom = tbodyDom.children[index].children[atflColumnIndex]; if (scwin.currentTabIndex === 0) { if (atrzOponCttYn === "Y" && ecazAtflYn === "Y") { // 케이스 1 : 의견, 첨부 둘 다 Y
scwin.dlt[scwin.currentTabIndex].setCellData(index, "opinion", "/pmb/cm/images/contents/skj_opinion.png")// 개발환경에서 경로를 못찾음. 로컬에선 찾음. scwin.dlt[scwin.currentTabIndex].setCellData(index, "atfl", "/pmb/cm/images/contents/skj_attach.png") } else if (atrzOponCttYn === "Y" && ecazAtflYn !== "Y") { // 케이스 2 : 의견만 Y // mergeCell (의견이미지 on) scwin.grd[scwin.currentTabIndex].mergeCell({rowIndex: index, colIndex: opinionColumnIndex, colSpan: 2}); // opinionCellDom.children[0].src = 'cm/images/contents/skj_opinion.png'; scwin.dlt[scwin.currentTabIndex].setCellData(index, "opinion", "/pmb/cm/images/contents/skj_opinion.png") } else if (atrzOponCttYn !== "Y" && ecazAtflYn === "Y") { // 케이스 3 : 첨부만 Y // 의견 src 없애기 (첨부이미지 on) scwin.grd[scwin.currentTabIndex].mergeCell({rowIndex: index, colIndex: opinionColumnIndex, colSpan: 2}); // opinionCellDom.innerHTML = opinionCellDom.getInnerHTML().replace("opinion", "attach"); // opinionCellDom.children[0].src = 'cm/images/contents/skj_attach.png'; scwin.dlt[scwin.currentTabIndex].setCellData(index, "opinion", "/pmb/cm/images/contents/skj_attach.png")
} else if (atrzOponCttYn !== "Y" && ecazAtflYn !== "Y") { // 케이스 4 : 의견, 첨부 둘 다 N // (의견, 첨부이미지 off) // 방법2)의견 src, 첨부 src 없애기 // opinionCellDom.children[0].src = ''; // atflCellDom.children[0].src = ''; scwin.grd[scwin.currentTabIndex].mergeCell({rowIndex: index, colIndex: opinionColumnIndex, colSpan: 2}); scwin.dlt[scwin.currentTabIndex].setCellData(index, "opinion", ""); scwin.dlt[scwin.currentTabIndex].setCellData(index, "atfl", ""); } } else { if (atrzOponCttYn === "Y") { // opinionCellDom.children[0].src = 'cm/images/contents/skj_opinion.png'; } else { // opinionCellDom.children[0].src = ''; } } }); }
}, 0); // 0초만 넣어도 프로세스 순서가 안꼬임. };
scwin.Dbclick = function(id) { var el = WebSquare.wUnit.getDomById(id); scwin.fireDbClick(el); } scwin.fireDbClick = function(node) { if (document.createEventObject) { node.fireEvent('ondblclick'); } else if (document.createEvent) { var evt = document.createEvent('MouseEvents'); evt.initEvent('dblclick', true, false); node.dispatchEvent(evt); } else if (typeof node.ondblclick == 'function') { node.ondblclick(); } } scwin.checkVal1 = function() { return WebSquare.wUnit.getDomById('mf_grd_doc_cell_5_8').getAttribute('colspan') == 2; } scwin.unitTest = function() { //Unit WebSquare.wUnit.start(); WebSquare.wUnit.addCommand("pause", "500"); WebSquare.wUnit.addCommand("set", "scwin.Dbclick('grd_doc_col5')"); WebSquare.wUnit.addCommand("pause", "500"); WebSquare.wUnit.addCommand("set", "scwin.Dbclick('grd_doc_col5')"); WebSquare.wUnit.addCommand("pause", "500"); WebSquare.wUnit.addCommand("assert", "scwin.checkVal1()","true"); WebSquare.wUnit.addCommand("pause", "500");
//Run test and stop WebSquare.wUnit.run(); WebSquare.wUnit.stop(); } scwin.unitTest()
